function _imageEncode(arrayBuffer){let u8=new Uint8Array(arrayBuffer);let b64encoded=btoa([].reduce.call(new Uint8Array(arrayBuffer),function(p,c){return p+String.fromCharCode(c);},""));let mimetype="image/jpeg";return "data:"+mimetype+";base64,"+b64encoded;}
function cargarRepositorio(repositorio){var listaImagenes="";listaImagenes+="\n        <div id='loading' >Cargando...</div>";listaImagenes+="\n        <div class='ayuda-repositorio'>";listaImagenes+="\n            <span class='ayuda-repositorio-span'>Haga doble clic para usar el icono en la zona dibujo</span>";listaImagenes+="\n        </div>";listaImagenes+="\n        <div id='divLista'></div>";document.getElementById("listaImagenes").innerHTML=listaImagenes;var loading=document.getElementById("loading");loading.style.display="block";var divLista=document.getElementById("divLista");axios.get("./repositorios/"+repositorio+"/lista.txt",{responseType:"text"}).then(function(res){if(res.status==200){var listaLineas=res.data.split("\n");listaLineas.forEach(linea=>{if(linea){var element=linea.split("|")[0];var tooltip=linea.split("|")[1]||element;var fondo=linea.split("|")[2]||"";axios.get("./repositorios/"+repositorio+"/thumbnails/"+element,{responseType:"arraybuffer"}).then(function(result){if(result.status==200){if(element!="lista.txt"&&element!=""){var funcion="insertarImagen";if(fondo==="tongaappfondo"||fondo==="tongaappfondo\r"){funcion="cargarFondo";}
var _img='<div class="divImagenRepositorio">'+
'<img class="imgImagenRepositorio" + src="'+
_imageEncode(result.data)+
'" name="'+
element+
'" alt="'+
element+
'" title="'+
tooltip+
'"  '+
' ondblclick="'+funcion+'(\''+repositorio+'\', this)" '+
'/>'+
'</div>';document.getElementById("divLista").innerHTML+=_img;}
loading.style.display="none";}}).catch(function(err){mensaje.innerText="Error de conexión "+err;}).then(function(){loading.style.display="none";});}});}}).catch(function(err){mensaje.innerText="Error de conexión "+err;}).then(function(){loading.style.display="none";});}
function insertarImagen(repositorio,img){var localURL="/repositorios/"+repositorio+"/"+img.alt;var request=new XMLHttpRequest();request.open('GET',localURL,true);request.responseType='blob';request.onload=function(imagen){var nombreFichero=imagen.srcElement.responseURL.substring(imagen.srcElement.responseURL.lastIndexOf('/')+1);var reader=new FileReader();reader.readAsDataURL(request.response);reader.onload=function(e){imgUrl=e.target.result;imageEditor.getActions()["imagen"].registerCustomImagen(imgUrl,nombreFichero);};};request.send();}
function cargarFondo(repositorio,img){var localURL="/repositorios/"+repositorio+"/"+img.alt;var request=new XMLHttpRequest();request.open('GET',localURL,true);request.responseType='blob';request.onload=function(imagen){var nombreFichero=imagen.srcElement.responseURL.substring(imagen.srcElement.responseURL.lastIndexOf('/')+1);var reader=new FileReader();reader.readAsDataURL(request.response);reader.onload=function(e){imgUrl=e.target.result;imageEditor._invoker._isLocked=false;imageEditor._graphics.restoreCanvasDimension();imageEditor.loadImageFromURL(imgUrl,nombreFichero).then(sizeValue=>{console.log(sizeValue);var canvas=imageEditor.getCanvas();canvas.setZoom(1);imageEditor.clearUndoStack();imageEditor.ui.activeMenuEvent();imageEditor.ui.resizeEditor({imageSize:sizeValue});imageEditor.setHeightImagenBackground(sizeValue.newHeight);imageEditor.setWidthImagenBackground(sizeValue.newWidth);imageEditor.setImagenBinario(imageEditor.getBackgroundImage().toDataURL({format:"jpeg"}));imageEditor._graphics.restoreCanvasDimension();});};};request.send();}